const norm = v => String(v || '').trim().toLowerCase();
const seen = new Set();
for (const i of $('Get Logged Leads').all()) {
  const n = norm(i.json['Company Name']);
  if (n) seen.add(n);
}
for (const i of $('Get Duplicate Leads').all()) {
  const n = norm(i.json['Company Name']);
  if (n) seen.add(n);
}
const leads = $('If').all();
const next = leads.find(i => norm(i.json.company_name) && !seen.has(norm(i.json.company_name)));
if (!next) return [];
return [{ json: next.json }];

