const src = $('Prepare Enriched Lead').item.json;
const lead = {
  company_name: src.company_name,
  website: src.website,
  contact_name: src.contact_name,
  email: src.email,
  contact_number: src.contact_number
};
const raw = $json.output?.[0]?.content?.[0]?.text;

if (!raw) {
  return {
    json: {
      ...lead,
      parse_ok: false,
      error: "No LLM text found"
    }
  };
}

try {
  // Remove ```json and ``` if the model adds Markdown fences
  const cleaned = raw
    .replace(/```json/gi, '')
    .replace(/```/g, '')
    .trim();

  const parsed = JSON.parse(cleaned);

  return {
    json: {
      ...lead,
      ...parsed,
      company_name: lead.company_name,
      parse_ok: true
    }
  };

} catch (error) {
  return {
    json: {
      ...lead,
      parse_ok: false,
      error: error.message,
      raw_output: raw
    }
  };
}

