const items = $input.all();

return items.map(item => {
  try {
    let raw =
      item.json.output?.[0]?.content?.[0]?.text ??
      item.json.output_text ??
      item.json.text ??
      item.json.output ??
      '';

    // If output is already an object
    if (typeof raw === 'object' && raw !== null) {
      return {
        json: {
          ...item.json,
          ...raw,
          parse_ok: true
        }
      };
    }

    // Remove Markdown code fences if the model added them
    raw = String(raw)
      .replace(/```json/gi, '')
      .replace(/```/g, '')
      .trim();

    const parsed = JSON.parse(raw);

    return {
      json: {
        ...item.json,
        ...parsed,
        parse_ok: true
      }
    };

  } catch (error) {
    return {
      json: {
        ...item.json,
        parse_ok: false,
        parse_error: error.message
      }
    };
  }
});

