parameters.jsCode:
const items = $input.all();

let hot = 0;
let medium = 0;
let low = 0;

const leads = items.map(item => item.json).filter(l => Object.keys(l).length > 0);

for (const lead of leads) {
  const category = String(lead.Category || lead.category || '').trim().toLowerCase();

  if (category === 'hot') hot++;
  else if (category === 'medium') medium++;
  else if (category === 'low') low++;
}

// Sort leads by score, highest first
const topLeads = [...leads]
  .sort((a, b) => {
    const scoreA = Number(a.Score ?? a.score ?? 0);
    const scoreB = Number(b.Score ?? b.score ?? 0);
    return scoreB - scoreA;
  })
  .slice(0, 5)
  .map((lead, index) => {
    const company = lead['Company Name'] || lead.company_name || 'Unknown';
    const score = lead.Score ?? lead.score ?? 0;
    return `${index + 1}. ${company} - ${score}/100`;
  })
  .join('\n');

return [
  {
    json: {
      total: leads.length,
      hot: hot,
      medium: medium,
      low: low,
      top_leads: topLeads
    }
  }
];
